import { Component, OnInit, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

import { Notification, NotificationsApiService } from './notifications-api.service';
import { ToastService } from '../shared/toast/toast.service';

@Component({
  selector: 'app-notification-list',
  templateUrl: './notification-list.component.html',
})
export class NotificationListComponent implements OnInit {
  private readonly api = inject(NotificationsApiService);
  private readonly toast = inject(ToastService);
  protected readonly notifications = signal<Notification[]>([]);

  async ngOnInit(): Promise<void> {
    await this.reload();
  }

  protected async reload(): Promise<void> {
    this.notifications.set(await firstValueFrom(this.api.list()));
  }

  protected async dismiss(n: Notification): Promise<void> {
    try {
      await firstValueFrom(this.api.dismiss(n.id));
    } catch {
      this.toast.error('notifications.dismiss.failed');
    }
    await this.reload();
  }

  protected async markRead(n: Notification): Promise<void> {
    try {
      await firstValueFrom(this.api.markRead(n.id));
    } catch {
      this.toast.error('notifications.markRead.failed');
    }
    await this.reload();
  }
}
